    : 0;

const surchargesFor = (item: Item): number =>
  curseSurchargeFor(item) + enchantSurchargeFor(item);

const quotePremium = (items: Item[]): number => {
  const policyBase = basePremium(items);
  const itemSurcharges = sumBy(items, surchargesFor);
  const firstInsurance = policyBase * FIRST_INSURANCE_RATE;
  return policyBase + itemSurcharges + firstInsurance + PROCESSING_FEE;
};

type QuoteStep = { op: "quote"; items: Item[] };
type Scenario = { customer: { yearsWithMHPCO: number }; steps: QuoteStep[] };

export const runScenario = (scenario: Scenario): { results: { premium: number }[] } => {
  const results = scenario.steps.map((step) => ({
    premium: quotePremium(step.items),
  }));
  return { results };
};

