const PROCESSING_FEE = 5;
const CURSE_SURCHARGE_RATE = 0.5;
const HIGH_ENCHANTMENT_RATE = 0.3;
const HIGH_ENCHANTMENT_THRESHOLD = 5;
const FIRST_INSURANCE_RATE = 0.1;
const LOYALTY_DISCOUNT_RATE = 0.2;
const LOYALTY_THRESHOLD_YEARS = 2;

type Customer = { yearsWithMHPCO: number };

const curseSurchargeFor = (item: Item): number =>
  item.cursed ? basePremium([item]) * CURSE_SURCHARGE_RATE : 0;

const enchantSurchargeFor = (item: Item): number =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
    ? basePremium([item]) * HIGH_ENCHANTMENT_RATE
    : 0;

const surchargesFor = (item: Item): number =>
  curseSurchargeFor(item) + enchantSurchargeFor(item);

const quotePremium = (items: Item[], customer: Customer): number => {
  const policyBase = basePremium(items);
  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_RATE;
  const loyaltyDiscount =
    customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS
      ? policyBase * LOYALTY_DISCOUNT_RATE
      : 0;
  const policyCharges =
    policyBase + firstInsuranceSurcharge - loyaltyDiscount;

  const itemSurcharges = sumBy(items, surchargesFor);

  return policyCharges + itemSurcharges + PROCESSING_FEE;
};

type QuoteStep = { op: "quote"; items: Item[] };
type Scenario = { customer: Customer; steps: QuoteStep[] };

export const runScenario = (scenario: Scenario): { results: { premium: number }[] } => {
  const results = scenario.steps.map((step) => ({
    premium: quotePremium(step.items, scenario.customer),
  }));
  return { results };
};

