const PROCESSING_FEE = 5;
const CURSE_SURCHARGE_RATE = 0.5;
const HIGH_ENCHANTMENT_RATE = 0.3;
const HIGH_ENCHANTMENT_THRESHOLD = 5;
const FIRST_INSURANCE_RATE = 0.1;
const LOYALTY_DISCOUNT_RATE = 0.2;
const LOYALTY_THRESHOLD_YEARS = 2;
const FOLLOW_UP_DISCOUNT_RATE = 0.15;

type Customer = { yearsWithMHPCO: number };

const curseSurchargeFor = (item: Item): number =>
  item.cursed ? basePremium([item]) * CURSE_SURCHARGE_RATE : 0;

const enchantSurchargeFor = (item: Item): number =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
    ? basePremium([item]) * HIGH_ENCHANTMENT_RATE
    : 0;

const surchargesFor = (item: Item): number =>
  curseSurchargeFor(item) + enchantSurchargeFor(item);

// Premiums round in MHPCO's favor — up. (Claim payouts will round down, also in MHPCO's favor.)
const roundInFavorUp = (amount: number): number => Math.ceil(amount);

const quotePremium = (
  items: Item[],
  customer: Customer,
  isFollowUp: boolean,
