const handleClaim = (step: ClaimStep): ClaimResult => {
  const policy = policies[step.policy];
  const desiredPayout = roundInFavorDown(
    sumBy(step.incident.damages, (damage) =>
      reimbursementFor(damage, policy.items),
    ),
  );
